import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.doxMM-x8.js";const b=JSON.parse('{"title":"Module Boundaries","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/module-boundaries","contentType":"concept","prev":{"text":"Project structure","link":"/en/architecture/project-structure"},"next":false},"headers":[],"relativePath":"en/architecture/module-boundaries.md","filePath":"en/architecture/module-boundaries.md"}'),o={name:"en/architecture/module-boundaries.md"};function r(i,e,c,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="module-boundaries" tabindex="-1">Module Boundaries <a class="header-anchor" href="#module-boundaries" aria-label="Permalink to &quot;Module Boundaries&quot;">​</a></h1><p>Lab Word reuses Core and Platform while keeping laboratory behavior separate. <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/docs/adr/0003-static-example-composition.md" target="_blank" rel="noreferrer">ADR 0003</a>and <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>record the target boundaries.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application entry ──composes──&gt; Universal shell + business contributions</span></span>
<span class="line"><span>Business Views ──────────────&gt; SDK / Core / UI</span></span>
<span class="line"><span>SDK ─────────────────────────&gt; Contracts</span></span>
<span class="line"><span>Business Application ────────&gt; Core public capabilities / Platform</span></span>
<span class="line"><span>Platform ────────────────────&gt; Infrastructure</span></span></code></pre></div><p>Application entry points choose composition. Core and the universal shell do not import concrete businesses. Platform does not depend on Application. Knowledge is currently a reference domain; Lab will own 3D assets and equipment concepts.</p><h2 id="current-public-interfaces" tabindex="-1">Current Public Interfaces <a class="header-anchor" href="#current-public-interfaces" aria-label="Permalink to &quot;Current Public Interfaces&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">composition contract</a>declares pages, navigation, messages and default entry. <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">Assembly validation</a>rejects duplicate ids, conflicting/reserved routes and missing translations. TanStack Router stays in the Web adapter.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API entry</a>composes Router and OpenAPI. Each Rust module declares table ownership in <code>module.json</code>; modules collaborate through public capabilities instead of accessing each other&#39;s tables. Business use cases own transactions; audit and jobs share the same connection where atomic commit is required.</p><h2 id="validation-and-limits" tabindex="-1">Validation And Limits <a class="header-anchor" href="#validation-and-limits" aria-label="Permalink to &quot;Validation And Limits&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>Static checks reject known dependency and ownership violations. They cannot establish dynamic SQL correctness, authorization or recovery. Observe those behaviors through HTTP and public capability checks; see the <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/docs/testing/strategy.md" target="_blank" rel="noreferrer">testing strategy</a>.</p><p>Independent businesses have distinct source ownership, not separate customer organizations. The application retains <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">one Organization per deployment</a>. Complete historical example manifests and removal tools are absent from this copy; target architecture does not establish implemented commands.</p><p>Lab <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/crates/app/src/modules/lab/module.json" target="_blank" rel="noreferrer">ownership</a> declares the subscription helper through exact <code>sdkPaths</code>, its SDK facade integration through <code>assemblyPoints</code>, and its exports in <code>contractSymbols</code>. Removing Lab includes those helpers, tests, tutorials, and Lab facade exports, followed by contract/SDK regeneration. Shared HTTP/SSE lifetimes remain owned by the SDK. Boundary checks allow only declared business SDK files to import that business&#39;s contracts; undeclared SDK files and Core retain the existing restrictions.</p><p>Production Lab validation must cover import failure, resource disposal, fast switching and lazy loading. See <a href="./lab-word">product scope</a>.</p><hr><p>Source version：<code>d3ff309e4aa6</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d3ff309e4aa61231802ec2fb38cdbe7c44d8e7e1/docs/architecture/module-boundaries.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,16)])])}const u=a(o,[["render",r]]);export{b as __pageData,u as default};
